INSERT INTO Movies (title,genre_id,duration_min,age_rating,release_year,rating,description) VALUES
(N'Алматы аспаны',1,112,12,2026,8.7,N'Үлкен қалада арманын іздеген жас музыканттың тағдыры.'),
(N'Жарық жылдамдығы',3,128,12,2026,8.9,N'Алыс ғаламшардан келген хабар адамзаттың жоспарын өзгертеді.'),
(N'Күлкі керуені',2,94,6,2025,8.2,N'Достардың күтпеген саяхаты көңілді оқиғаларға толы.'),
(N'Түнгі із',8,118,16,2026,8.3,N'Детектив жасырын дәлелдер арқылы ескі істі қайта ашады.'),
(N'Жасыл ғалам',6,88,0,2025,8.4,N'Балалар табиғатты сақтаудың ерекше жолын табады.'),
(N'Уақыт қақпасы',3,134,12,2026,9.1,N'Ғалымдар уақыт ағынының жұмбақ заңдылығын зерттейді.'),
(N'Қаладағы кездесу',2,102,12,2026,7.9,N'Кездейсоқ таныстық жаңа достыққа айналады.'),
(N'Мұзды шың',7,126,12,2025,8.5,N'Экспедиция биік тауда маңызды шешімге келеді.'),
(N'Соңғы вагон',4,109,16,2026,8.1,N'Түнгі пойыздағы құпия жолаушыларды алаңдатады.'),
(N'Арман бағы',5,96,0,2025,8.6,N'Үш ұрпақ бір шаңырақта өмірдің құндылығын таниды.'),
(N'Құпия код',8,123,12,2026,8.8,N'Бағдарламашы түсініксіз деректердің астарын ашады.'),
(N'Көрінбейтін жол',7,116,12,2026,8.0,N'Жас зерттеушілер белгісіз бағытпен сапарға шығады.'),
(N'Көңілді роботтар',6,91,0,2026,8.3,N'Кішкентай роботтар достықтың күшін көрсетеді.'),
(N'Алыстағы үй',1,132,16,2025,8.6,N'Отбасы бірнеше жылдан соң туған жеріне оралады.'),
(N'Жеңіс формуласы',9,121,12,2026,8.1,N'Жарысқа қатысушылар бір мақсат үшін бірігеді.'),
(N'Бір күндік демалыс',2,98,6,2025,7.7,N'Әріптестердің жоспарсыз демалысы ерекше өтеді.'),
(N'Ғарыштағы дос',5,104,6,2026,8.8,N'Жасөспірім бөтен планетада жаңа дос табады.'),
(N'Жоғалған хаттар',1,114,12,2025,8.4,N'Ескі хаттар отбасының өткен тарихын ашады.'),
(N'Шекарадағы таң',9,125,16,2026,8.2,N'Құтқару тобы қиын тапсырманы орындайды.'),
(N'Орман сақшылары',6,86,0,2025,8.5,N'Жануарлар бірге ормандарын қорғайды.'),
(N'Жаңбыр астындағы әуен',1,108,12,2026,7.9,N'Әуен арқылы қайта табысқан достар туралы оқиға.'),
(N'Ақылды қала',3,130,12,2026,8.7,N'Болашақтағы қаланың басқару жүйесі күтпеген сынаққа түседі.'),
(N'Сағат он екіде',4,111,16,2025,8.0,N'Бір түнде ашылған құпия бірнеше адамның тағдырын өзгертеді.'),
(N'Таңғы экспресс',7,117,6,2026,8.3,N'Көршілер жаңа бағыттағы пойызда танысады.');
